-- Original visible, usable, unlocked ALL doors on qualified public maps only.
CREATE TABLE environment_door_definitions (
    map_id integer NOT NULL CHECK (map_id > 0),
    object_id bigint NOT NULL CHECK (object_id > 0),
    x integer NOT NULL,
    y integer NOT NULL,
    z integer NOT NULL,
    initial_state smallint NOT NULL CHECK (initial_state IN (0, 1)),
    payload_sha256 text NOT NULL CHECK (length(payload_sha256) = 64),
    state_payload_hex text NOT NULL,
    PRIMARY KEY (map_id, object_id)
);

CREATE TABLE environment_door_states (
    map_id integer NOT NULL,
    instance_id bigint NOT NULL CHECK (instance_id >= 0),
    object_id bigint NOT NULL,
    state smallint NOT NULL CHECK (state IN (0, 1)),
    PRIMARY KEY (map_id, instance_id, object_id),
    FOREIGN KEY (map_id, object_id)
        REFERENCES environment_door_definitions(map_id, object_id)
);

-- Explicit local policy: native NO_GROUP + ALL + visible/usable + unlocked,
-- with no attached scripts/criteria and an exact native walkable collision cell.
